package com.jagan.healthcare.controller;
import com.jagan.healthcare.dto.ChatRequest; import com.jagan.healthcare.dto.ChatResponse; import com.jagan.healthcare.model.ChatInteraction; import com.jagan.healthcare.repository.ChatInteractionRepository; import com.jagan.healthcare.service.ChatbotService; import jakarta.servlet.http.HttpSession; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/chat") @CrossOrigin(origins="*") public class ChatController { private final ChatbotService chatbotService; private final ChatInteractionRepository chatRepository; public ChatController(ChatbotService chatbotService,ChatInteractionRepository chatRepository){this.chatbotService=chatbotService;this.chatRepository=chatRepository;} @PostMapping public ResponseEntity<ChatResponse> chat(@Valid @RequestBody ChatRequest request){ if(request.getSeverity()!=null&&!request.getSeverity().trim().isEmpty()) return ResponseEntity.ok(chatbotService.processSeverity(request.getMessage(),request.getSeverity())); return ResponseEntity.ok(chatbotService.processMessage(request.getMessage())); } @DeleteMapping("/history") public Map<String,String> clearHistory(){chatRepository.deleteAll();return Map.of("message","Chat history cleared.");} @GetMapping("/history") public List<ChatInteraction> history(){List<ChatInteraction> all=chatRepository.findAllByOrderByCreatedAtDesc(); Collections.reverse(all); return all.size()>50?all.subList(Math.max(0,all.size()-50),all.size()):all;} }
